public int pairsBrute(int[] arr, int k) {
    int n = arr.length, count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (Math.abs((long) arr[i] - arr[j]) == k) {
                count++;
            }
        }
    }
    return count;
}

