code.java:
public int pairs(int[] arr, int k) {
    java.util.Arrays.sort(arr);
    int count = 0;
    for (int x : arr) {
        if (binarySearch(arr, (long) x + k)) {
            count++;
        }
    }
    return count;
}

private boolean binarySearch(int[] arr, long target) {
    int lo = 0, hi = arr.length - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >>> 1;
        if (arr[mid] == target) return true;
        if (arr[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return false;
}

