from bisect import bisect_left

def pairs(arr: list[int], k: int) -> int:
    arr.sort()
    count = 0
    for x in arr:
        target = x + k
        i = bisect_left(arr, target)
        if i < len(arr) and arr[i] == target:
            count += 1
    return count
